/* Owned harmless native process probe. No model, credentials or network. */
#include <stdio.h>
#include <sys/stat.h>
#include <unistd.h>
int main(int argc, char **argv) {
  if(argc!=2)return 2;
  FILE *in=fopen("/bin/sh","rb"), *out=fopen(argv[1],"wb");
  if(!in||!out){perror("open");return 3;}
  unsigned char b[8192]; size_t n;
  while((n=fread(b,1,sizeof b,in))>0)if(fwrite(b,1,n,out)!=n)return 4;
  fclose(in);fclose(out);
  if(chmod(argv[1],0700)){perror("chmod");return 5;}
  char *args[]={argv[1],"-c","printf TARGET_COPY_SHELL_EXECUTED",NULL};
  execv(argv[1],args);perror("execv");return 6;
}

