#include <stdio.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <stdlib.h>
#include <errno.h>
int main(int argc,char **argv){
 if(argc!=4)return 10;
 int fd=open(argv[1],O_WRONLY|O_APPEND);printf("DIRECT_OPEN=%d ERRNO=%d\n",fd,errno);if(fd>=0){close(fd);return 11;}
 int link_rc=link(argv[1],argv[2]);printf("HARDLINK=%d ERRNO=%d\n",link_rc,errno);
 if(link_rc==0){fd=open(argv[2],O_WRONLY|O_APPEND);printf("ALIAS_OPEN=%d ERRNO=%d\n",fd,errno);if(fd>=0){close(fd);return 12;}}
 int r=system("printf UNEXPECTED_SHELL_EXECUTION");printf("SHELL_STATUS=%d\n",r);if(r==0)return 13;
 fd=open(argv[3],O_WRONLY|O_CREAT,0600);printf("TEMP_OPEN=%d ERRNO=%d\n",fd,errno);if(fd<0)return 14;close(fd);
 return 0;
}
